// Generated by MythAgentic. Registers this website's agent actions with the agentify-website
// runtime, for the spots the owner approved. The spots are listed in placement.json, next to
// this file. Only the names in agent-manifest.json "actions.agentTools" become model tools,
// called website_<name>.
//
// Every action uses the page itself: a form helper fills the page's own form and sends it
// through the page's own submit handler, and read actions read the site's own pages. No site
// data is copied into this file or into the agent's instructions.

import { trustedHtml } from "./runtime/trusted-types.js";

/** Most characters a read action returns, so one page cannot fill the model's context. */
const MAX_TEXT = 12000;

/**
 * Text of a node with whitespace squeezed and a space between elements.
 * @param {Node|null} node
 */
function textOf(node) {
  if (!node) return "";
  const parts = [];
  const walk = (n) => {
    if (n.nodeType === 3) parts.push(n.data);
    else if (n.nodeType === 1 && !["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE"].includes(n.tagName)) for (const c of n.childNodes) walk(c);
    if (n.nodeType === 1) parts.push(" ");
  };
  walk(node);
  return parts.join("").replace(/\s+/g, " ").trim();
}

/**
 * The actions for the approved spots.
 */
export class PackActions {
  /** The parsed placement.json, once loaded. */
  static placement = null;

  /** The folder that holds this file: the site's root. */
  static base = new URL("./", import.meta.url);

  /**
   * Load placement.json and register one set of actions per approved spot.
   * :param actions: The runtime registry facade with a register(definition) method.
   */
  static async registerActions(actions) {
    const placement = await PackActions.load();
    for (const spot of placement.spots) {
      if (spot.kind === "form") {
        actions.register(PackActions.fillAction(spot));
        actions.register(PackActions.submitAction(spot));
      } else if (spot.kind === "answers") {
        actions.register(PackActions.readAnswersAction(spot));
      } else if (spot.kind === "compare") {
        actions.register(PackActions.listOptionsAction(spot));
      }
    }
    if (placement.contact) actions.register(PackActions.contactAction(placement.contact));
  }

  /** Load placement.json once. */
  static async load() {
    if (!PackActions.placement) {
      const response = await fetch(new URL("placement.json", PackActions.base), { cache: "no-store" });
      if (!response.ok) throw new Error(`placement.json is unavailable: HTTP ${response.status}.`);
      PackActions.placement = await response.json();
    }
    return PackActions.placement;
  }

  /** Use a placement already in memory (Node tests). */
  static usePlacement(placement) {
    PackActions.placement = placement;
  }

  /**
   * The page URL for a site path such as "/book.html".
   * @param {string} path
   */
  static pageUrl(path) {
    return new URL(path.replace(/^\//, ""), PackActions.base);
  }

  /**
   * Whether the visitor is on the page with this path.
   * @param {string} path
   */
  static onPage(path) {
    const here = new URL(document.URL);
    const there = PackActions.pageUrl(path);
    const strip = (p) => p.replace(/index\.html$/, "");
    return strip(here.pathname) === strip(there.pathname);
  }

  /**
   * This spot's form on the current page, or null.
   * @param {object} spot
   */
  static formOf(spot) {
    if (!PackActions.onPage(spot.path)) return null;
    if (spot.formId) return document.getElementById(spot.formId);
    return document.forms[spot.formIndex - 1] ?? null;
  }

  /**
   * The JSON schema for one form field.
   * @param {object} field
   */
  static fieldSchema(field) {
    const description = field.label || field.placeholder || field.name;
    if ((field.type === "select" || field.type === "radio") && field.choices.length > 0) {
      return { type: "string", enum: field.choices, description };
    }
    if (field.type === "checkbox") return { type: "boolean", description };
    if (field.type === "number") return { type: "integer", description };
    // The runtime accepts a small JSON Schema subset: no "pattern", and only the
    // "date" and "email" formats (runtime/actions.js checkSchema).
    if (field.type === "date") return { type: "string", format: "date", description: `${description} (YYYY-MM-DD)` };
    if (field.type === "email") return { type: "string", format: "email", maxLength: 200, description };
    if (field.type === "time") return { type: "string", maxLength: 5, description: `${description} (HH:MM, 24-hour)` };
    return { type: "string", maxLength: field.type === "textarea" ? 1000 : 200, description };
  }

  /**
   * A write action that fills the form, and sends nothing.
   * @param {object} spot
   */
  static fillAction(spot) {
    const properties = {};
    for (const field of spot.fields) properties[field.name] = PackActions.fieldSchema(field);
    return {
      name: spot.fillName,
      description: `Fill the "${spot.title}" form on ${spot.path} with details the visitor gave. Pass only the fields they gave; never invent values. It fills the visible form, which the visitor can still change, and sends nothing. Returns the filled fields and the required fields still empty. Works only while the visitor is on ${spot.path}.`,
      effect: "write",
      inputSchema: { type: "object", additionalProperties: false, properties },
      execute: (args) => PackActions.fill(spot, args),
    };
  }

  /**
   * Fill a form through its own controls, so the page's own events run.
   * @param {object} spot
   * @param {Record<string, unknown>} args
   */
  static fill(spot, args) {
    const form = PackActions.formOf(spot);
    if (!form) return { ok: false, reason: `This form is on another page. Ask the visitor to open ${PackActions.pageUrl(spot.path).href} first.` };
    const filled = [];
    for (const [name, value] of Object.entries(args)) {
      const controls = [...form.elements].filter((el) => el.name === name);
      if (controls.length === 0) continue;
      const first = controls[0];
      if (first.type === "radio") {
        for (const radio of controls) radio.checked = radio.value === String(value);
      } else if (first.type === "checkbox") {
        first.checked = value === true;
      } else if (first.tagName === "SELECT") {
        const option = [...first.options].find((o) => o.value === String(value) || o.text === String(value));
        if (!option) return { ok: false, reason: `"${value}" is not an option for ${name}.`, field: name };
        first.value = option.value;
      } else {
        first.value = String(value);
      }
      first.dispatchEvent(new Event("input", { bubbles: true }));
      first.dispatchEvent(new Event("change", { bubbles: true }));
      filled.push(name);
    }
    return { ok: true, filled, stillEmpty: PackActions.missing(form), note: "Nothing was sent. The visitor can check the form on the page." };
  }

  /**
   * Labels of required fields that are still empty or invalid.
   * @param {HTMLFormElement} form
   */
  static missing(form) {
    const out = new Set();
    for (const el of form.elements) {
      if (!el.name || el.checkValidity()) continue;
      const label = el.labels?.[0]?.textContent?.trim() || el.getAttribute("aria-label") || el.name;
      out.add(label);
    }
    return [...out];
  }

  /**
   * The form's current values, by field label, for the confirmation dialog.
   * @param {object} spot
   */
  static values(spot) {
    const form = PackActions.formOf(spot);
    if (!form) return {};
    const out = {};
    for (const field of spot.fields) {
      const controls = [...form.elements].filter((el) => el.name === field.name);
      let value = "";
      if (controls[0]?.type === "radio") value = controls.find((c) => c.checked)?.value ?? "";
      else if (controls[0]?.type === "checkbox") value = controls[0].checked ? "Yes" : "";
      else value = controls[0]?.value ?? "";
      if (value) out[field.label || field.name] = value;
    }
    return out;
  }

  /**
   * An irreversible action that sends the form as it is now. The browser asks first.
   * @param {object} spot
   */
  static submitAction(spot) {
    return {
      name: spot.submitName,
      description: `Send the "${spot.title}" form as it is now on ${spot.path}, through the page's own "${spot.submitText || "Submit"}" button. Call website_${spot.fillName} first. The browser shows the visitor the details and asks them to confirm. Returns ok false with the missing fields if the form is not complete.`,
      effect: "irreversible",
      inputSchema: { type: "object", additionalProperties: false, properties: {} },
      execute: () => PackActions.submit(spot),
    };
  }

  /**
   * Check the form, then send it through its own submit button.
   * @param {object} spot
   */
  static check(spot) {
    const form = PackActions.formOf(spot);
    if (!form) return { ok: false, reason: `This form is on another page: ${PackActions.pageUrl(spot.path).href}.` };
    const missing = PackActions.missing(form);
    if (missing.length > 0) return { ok: false, reason: `Still needed: ${missing.join(", ")}.`, missing };
    return { ok: true, form };
  }

  /** @param {object} spot */
  static submit(spot) {
    const check = PackActions.check(spot);
    if (!check.ok) return check;
    const sent = PackActions.values(spot);
    check.form.requestSubmit();
    return { ok: true, sent, note: "Sent through the page's own form. The page shows what happens next." };
  }

  /**
   * Read a same-origin page of this site.
   * @param {string} path
   */
  static async readPage(path) {
    const url = PackActions.pageUrl(path);
    const response = await fetch(url, { credentials: "same-origin", cache: "no-store" });
    if (!response.ok) throw new Error(`Could not read ${url.href}: HTTP ${response.status}.`);
    const doc = new DOMParser().parseFromString(trustedHtml(await response.text()), "text/html");
    // The page may carry this assistant's own section; it is not site content.
    doc.querySelector("#assistant")?.remove();
    return { doc, url: url.href, main: doc.querySelector("main") ?? doc.body };
  }

  /** @param {object} spot */
  static readAnswersAction(spot) {
    return {
      name: spot.readName,
      description: `Read the questions and answers on "${spot.title}" (${spot.path}). Call it before answering any question about ${spot.topics}. Returns each question with its answer and the page URL to cite.`,
      effect: "read",
      inputSchema: { type: "object", additionalProperties: false, properties: {} },
      execute: () => PackActions.readAnswers(spot),
    };
  }

  /** @param {object} spot */
  static async readAnswers(spot) {
    const { main, url } = await PackActions.readPage(spot.path);
    const answers = [];
    let current = null;
    for (const el of main.querySelectorAll("h1, h2, h3, h4, summary, p, li, dd")) {
      if (/^H[1-4]$|^SUMMARY$/.test(el.tagName)) {
        current = { question: textOf(el), answer: "" };
        answers.push(current);
      } else if (current) {
        current.answer = `${current.answer} ${textOf(el)}`.trim();
      }
    }
    const items = answers.filter((a) => a.answer);
    return { ok: true, url, items: PackActions.limit(items) };
  }

  /** @param {object} spot */
  static listOptionsAction(spot) {
    return {
      name: spot.listName,
      description: `List every option in the table on "${spot.title}" (${spot.path}), with all its columns and its page link. Call it before comparing or recommending options. Returns the rows exactly as the site shows them.`,
      effect: "read",
      inputSchema: { type: "object", additionalProperties: false, properties: {} },
      execute: () => PackActions.listOptions(spot),
    };
  }

  /** @param {object} spot */
  static async listOptions(spot) {
    const { main, url } = await PackActions.readPage(spot.path);
    const table = main.querySelectorAll("table")[spot.tableIndex];
    if (!table) return { ok: false, reason: "The table is no longer on the page." };
    const rows = [...table.querySelectorAll("tr")];
    const columns = [...rows[0].querySelectorAll("th, td")].map(textOf);
    const options = rows.slice(1).map((row) => {
      const cells = [...row.querySelectorAll("th, td")];
      const option = {};
      cells.forEach((cell, i) => { option[columns[i] || `Column ${i + 1}`] = textOf(cell); });
      const link = row.querySelector("a[href]");
      if (link) option.link = new URL(link.getAttribute("href"), url).href;
      return option;
    });
    return { ok: true, url, columns, options: PackActions.limit(options) };
  }

  /** @param {{path:string, title:string}} contact */
  static contactAction(contact) {
    return {
      name: "read_contact",
      description: `Read the site's contact page (${contact.path}): address, phone, email and opening hours if it lists them. Call it when the visitor asks how to reach the business, or for anything this assistant cannot do.`,
      effect: "read",
      inputSchema: { type: "object", additionalProperties: false, properties: {} },
      execute: async () => {
        const { main, url } = await PackActions.readPage(contact.path);
        return { ok: true, url, text: textOf(main).slice(0, MAX_TEXT) };
      },
    };
  }

  /**
   * Keep a result under MAX_TEXT characters.
   * @param {unknown[]} items
   */
  static limit(items) {
    const out = [];
    let size = 0;
    for (const item of items) {
      size += JSON.stringify(item).length;
      if (size > MAX_TEXT) break;
      out.push(item);
    }
    return out;
  }
}

// The runtime calls the module's registerActions export.
export const registerActions = PackActions.registerActions;
